// ##################

import { useState, useEffect } from "react";
import { createFileRoute } from "@tanstack/react-router";
import { useQuery, useMutation } from "@tanstack/react-query";
import { trpc } from "@/utils/trpc";
import { pageHead } from "@/utils/page-head";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Calendar } from "@/components/ui/calendar";
import { cn } from "@/lib/utils";
import dayjs from "dayjs";
import "dayjs/locale/id"; // Use Indonesian locale for date rendering
import {
  Calendar as CalendarIcon,
  Check,
  ChevronLeft,
  ChevronRight,
  Download,
  ShieldAlert,
  Clock,
  Video,
  MapPin,
  Award,
} from "lucide-react";

// Set dayjs locale to Indonesian
dayjs.locale("id");

export const Route = createFileRoute(
  "/(core)/dashboard/pelatihan/$enrollmentId/jadwal-presensi",
)({
  head: () => pageHead("Jadwal & Presensi Pelatihan"),
  component: RouteComponent,
});

/**
 * Komponen utama halaman Jadwal & Presensi Bimtek untuk peserta.
 *
 * Menampilkan progress kehadiran peserta, periode pelatihan,
 * pemilih tanggal (kalender), jadwal kelas per hari, serta modal check-in presensi.
 */
function RouteComponent() {
  const { enrollmentId } = Route.useParams();

  // 1. Fetch schedules & attendances data
  const { data, isLoading, refetch } = useQuery(
    trpc.pelatihan.enrollment.getBimtekSchedules.queryOptions({
      enrollmentId,
    }),
  );

  const [selectedDate, setSelectedDate] = useState<Date>(new Date());
  const [selectedScheduleForAbsen, setSelectedScheduleForAbsen] =
    useState<any>(null);
  const [attendanceStatus, setAttendanceStatus] = useState<
    "present" | "excused"
  >("present");
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Initialize selectedDate to the first schedule's date if available
  useEffect(() => {
    if (data?.schedules?.[0]?.sessionDate) {
      setSelectedDate(new Date(data.schedules[0].sessionDate));
    }
  }, [data]);

  // Check-in mutation using tRPC
  const checkInMutation = useMutation(
    trpc.pelatihan.enrollment.checkInBimtek.mutationOptions({
      onSuccess: async () => {
        await refetch();
        setIsDialogOpen(false);
      },
    }),
  );

  if (isLoading) {
    return (
      <div className="flex h-64 items-center justify-center">
        <div className="text-center text-muted-foreground">
          Memuat jadwal dan presensi...
        </div>
      </div>
    );
  }

  if (!data) {
    return (
      <div className="p-8 text-center text-destructive">
        Gagal mengambil data jadwal pelatihan.
      </div>
    );
  }

  const { schedules, stats, enrollment } = data;
  const { pelatihan } = enrollment;

  // Format training period dates
  const startDateStr = pelatihan.startDate
    ? dayjs(pelatihan.startDate).format("D MMMM")
    : "";
  const endDateStr = pelatihan.endDate
    ? dayjs(pelatihan.endDate).format("D MMMM YYYY")
    : "";
  const periodStr =
    startDateStr && endDateStr
      ? `${startDateStr} - ${endDateStr}`
      : "Belum ditentukan";

  // Filter schedules for the currently selected date
  const selectedDateStr = dayjs(selectedDate).format("YYYY-MM-DD");
  const filteredSchedules = schedules.filter(
    (s) => dayjs(s.sessionDate).format("YYYY-MM-DD") === selectedDateStr,
  );

  // Date navigation handlers
  const handlePrevDay = () => {
    setSelectedDate((prev) => {
      const d = new Date(prev);
      d.setDate(d.getDate() - 1);
      return d;
    });
  };

  const handleNextDay = () => {
    setSelectedDate((prev) => {
      const d = new Date(prev);
      d.setDate(d.getDate() + 1);
      return d;
    });
  };

  // Click Presensi button on schedule card
  const openPresensiModal = (schedule: any) => {
    setSelectedScheduleForAbsen(schedule);
    setAttendanceStatus("present"); // default option
    setIsDialogOpen(true);
  };

  // Submit attendance check-in
  const handleCheckIn = async () => {
    if (!selectedScheduleForAbsen) return;
    setIsSubmitting(true);
    try {
      await checkInMutation.mutateAsync({
        enrollmentId,
        scheduleId: selectedScheduleForAbsen.id,
        status: attendanceStatus,
      });
      await refetch();
      setIsDialogOpen(false);
    } catch (e) {
      console.error(e);
    } finally {
      setIsSubmitting(false);
    }
  };

  // Circular progress dimensions
  const percentage = stats?.attendancePercentage ?? 0;
  const radius = 32;
  const circumference = 2 * Math.PI * radius;
  const strokeDashoffset = circumference - (percentage / 100) * circumference;

  return (
    <div className="mx-auto max-w-5xl space-y-8">
      {/* Header Pelatihan */}
      <div className="space-y-2 border-b border-slate-100 pb-4">
        <h1 className="text-3xl font-bold tracking-tight text-slate-900">
          {pelatihan.title}
        </h1>
        <p className="text-sm font-semibold text-[#1061D6]">
          Instruktur: {pelatihan.instructorName || "Tidak ada instruktur"}
        </p>
      </div>

      <div className="grid gap-8 md:grid-cols-3">
        {/* Left Side: Progress, Period & Notice Cards */}
        <div className="space-y-6 md:col-span-1">
          {/* Card Progress Kehadiran (Hanya jika absensi diaktifkan) */}
          {pelatihan.attendanceRequired ? (
            <Card className="overflow-hidden rounded-2xl border border-blue-100 bg-white shadow-[0px_0px_100px_-2px_rgba(16,97,214,0.04)]">
              <CardContent className="flex flex-col gap-4 p-5">
                <div className="flex items-center justify-between">
                  <div className="space-y-1">
                    <span className="text-xs font-semibold tracking-wider text-[#1061D6] uppercase">
                      Status Anda
                    </span>
                    <h3 className="text-lg font-bold text-slate-800">
                      Progress Kehadiran
                    </h3>
                  </div>
                  {/* Circular Indicator */}
                  <div className="relative flex items-center justify-center">
                    <svg className="h-20 w-20 -rotate-90 transform">
                      <circle
                        cx="40"
                        cy="40"
                        r={radius}
                        className="stroke-slate-100"
                        strokeWidth="6"
                        fill="transparent"
                      />
                      <circle
                        cx="40"
                        cy="40"
                        r={radius}
                        className={cn(
                          "transition-all duration-300",
                          percentage >=
                            (pelatihan.minAttendancePercentage ?? 85)
                            ? "stroke-emerald-500"
                            : "stroke-[#1061D6]",
                        )}
                        strokeWidth="6"
                        fill="transparent"
                        strokeDasharray={circumference}
                        strokeDashoffset={strokeDashoffset}
                        strokeLinecap="round"
                      />
                    </svg>
                    <span className="absolute text-sm font-bold text-slate-800">
                      {percentage}%
                    </span>
                  </div>
                </div>

                <div className="h-px w-full bg-slate-100" />

                {/* Min Requirement Badge */}
                <div className="flex items-start gap-3 rounded-lg border border-red-100 bg-red-50/50 p-3 text-red-700">
                  <ShieldAlert className="mt-0.5 h-5 w-5 shrink-0 text-red-600" />
                  <div className="text-xs leading-relaxed font-semibold">
                    Syarat Sertifikasi
                    <br />
                    Presensi min {pelatihan.minAttendancePercentage ?? 85}%
                  </div>
                </div>
              </CardContent>
            </Card>
          ) : (
            /* Jika absensi tidak diaktifkan, tampilkan kartu info premium absensi bebas */
            <Card className="overflow-hidden rounded-2xl border border-emerald-100 bg-emerald-50/20 shadow-[0px_0px_100px_-2px_rgba(16,97,214,0.04)]">
              <CardContent className="flex flex-col gap-4 p-5">
                <div className="flex items-start gap-4">
                  <div className="rounded-xl bg-emerald-50 p-3 text-emerald-600">
                    <Award className="h-6 w-6 stroke-[2]" />
                  </div>
                  <div className="space-y-1">
                    <span className="text-xs font-semibold tracking-wider text-emerald-600 uppercase">
                      Status Presensi
                    </span>
                    <h3 className="text-base font-bold text-slate-800">
                      Kehadiran Bebas
                    </h3>
                  </div>
                </div>
                <div className="h-px w-full bg-emerald-100/60" />
                <p className="text-xs leading-relaxed font-medium text-slate-600">
                  Untuk pelatihan ini, kelulusan tidak ditentukan oleh
                  kehadiran. Anda cukup menyelesaikan semua materi dan ujian
                  yang tersedia.
                </p>
              </CardContent>
            </Card>
          )}

          {/* Card Periode Pelatihan */}
          <Card className="rounded-2xl border border-blue-100 bg-white shadow-[0px_0px_100px_-2px_rgba(16,97,214,0.04)]">
            <CardContent className="flex items-start gap-4 p-5">
              <div className="rounded-xl bg-blue-50 p-3 text-[#1061D6]">
                <CalendarIcon className="h-6 w-6" />
              </div>
              <div className="space-y-1">
                <span className="text-xs font-semibold tracking-wider text-slate-400 uppercase">
                  PERIODE PELATIHAN
                </span>
                <p className="text-base font-bold text-[#1061D6]">
                  {periodStr}
                </p>
              </div>
            </CardContent>
          </Card>

          {/* Card Catatan Penting */}
          <Card
            className={cn(
              "rounded-2xl border shadow-sm",
              pelatihan.attendanceRequired
                ? "border-red-100 bg-red-50/20"
                : "border-blue-100 bg-blue-50/20",
            )}
          >
            <CardContent className="space-y-3 p-5">
              <div
                className={cn(
                  "flex items-center gap-2",
                  pelatihan.attendanceRequired
                    ? "text-red-700"
                    : "text-[#1061D6]",
                )}
              >
                <ShieldAlert className="h-5 w-5" />
                <h4 className="text-sm font-bold">CATATAN PENTING</h4>
              </div>
              <p className="text-xs leading-relaxed font-medium text-slate-600">
                {pelatihan.attendanceRequired
                  ? "Jadwal di atas bersifat tentatif dan dapat berubah sewaktu-waktu menyesuaikan pemateri dari Kemnaker RI. Peserta wajib hadir 15 menit sebelum sesi dimulai untuk pengecekan presensi."
                  : "Jadwal sesi bersifat tentatif. Karena kehadiran bersifat opsional, Anda dapat mengikuti sesi live secara langsung atau mengakses rekaman materi/sesi jika tersedia di luar jam kelas."}
              </p>
            </CardContent>
          </Card>
        </div>

        {/* Right Side: Schedules Timeline */}
        <div className="space-y-6 md:col-span-2">
          {/* Day Selector */}
          <div className="flex items-center justify-between rounded-2xl border border-slate-100 bg-white p-4 shadow-[0px_0px_100px_-2px_rgba(16,97,214,0.04)]">
            <div className="flex items-center gap-2">
              <Button
                variant="outline"
                size="icon"
                onClick={handlePrevDay}
                className="h-10 w-10 rounded-xl border-slate-200 bg-white shadow-sm transition-all hover:scale-[1.02] active:scale-[0.98]"
              >
                <ChevronLeft className="h-4 w-4" />
              </Button>

              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant="outline"
                    className="flex h-10 items-center gap-2 rounded-xl border-slate-200 bg-white px-4 text-sm font-semibold text-slate-800 shadow-sm transition-all hover:scale-[1.01] hover:bg-slate-50 active:scale-[0.98]"
                  >
                    <CalendarIcon className="h-4 w-4 text-[#1061D6]" />
                    {dayjs(selectedDate).format("dddd, D MMMM YYYY")}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className="w-auto p-0" align="start">
                  <Calendar
                    mode="single"
                    selected={selectedDate}
                    onSelect={(date) => date && setSelectedDate(date)}
                    initialFocus
                  />
                </PopoverContent>
              </Popover>

              <Button
                variant="outline"
                size="icon"
                onClick={handleNextDay}
                className="h-10 w-10 rounded-xl border-slate-200 bg-white shadow-sm transition-all hover:scale-[1.02] active:scale-[0.98]"
              >
                <ChevronRight className="h-4 w-4" />
              </Button>
            </div>

            {/* Jump to Today Button */}
            <Button
              variant="ghost"
              size="sm"
              onClick={() => setSelectedDate(new Date())}
              className="rounded-xl px-3 text-xs font-bold text-[#1061D6] transition-all hover:scale-[1.02] hover:bg-blue-50 active:scale-[0.98]"
            >
              Hari Ini
            </Button>
          </div>

          {/* Timeline list of schedule cards */}
          <div className="space-y-4">
            {filteredSchedules.length === 0 ? (
              <div className="border-slate-250 flex flex-col items-center justify-center rounded-2xl border border-dashed bg-slate-50/50 p-12 text-center">
                <CalendarIcon className="mb-3 h-10 w-10 text-slate-300" />
                <p className="text-sm font-semibold text-slate-700">
                  Tidak ada jadwal kelas
                </p>
                <p className="mt-1 text-xs text-slate-500">
                  Jadwal tidak tersedia untuk hari{" "}
                  {dayjs(selectedDate).format("dddd, D MMMM YYYY")}.
                </p>
              </div>
            ) : (
              filteredSchedules.map((schedule) => {
                const isCheckedIn = !!schedule.attendance;
                const attendanceType = schedule.attendance?.status;

                return (
                  <div
                    key={schedule.id}
                    className="flex overflow-hidden rounded-2xl border border-slate-100 bg-white shadow-sm transition-all hover:shadow-md"
                  >
                    {/* Left highlight strip */}
                    <div className="w-2 shrink-0 bg-[#1061D6]" />

                    <div className="flex-1 space-y-4 p-5 md:p-6">
                      {/* Badge / Info Header */}
                      <div className="flex flex-wrap items-center justify-between gap-3">
                        <div className="flex items-center gap-2">
                          <span className="inline-flex items-center rounded-lg bg-red-50 px-2.5 py-1 text-xs font-semibold text-red-600">
                            <Clock className="mr-1.5 h-3.5 w-3.5" />
                            {schedule.startTime} - {schedule.endTime}
                          </span>

                          {schedule.category && (
                            <span className="inline-flex items-center rounded-lg bg-blue-50 px-2.5 py-1 text-xs font-semibold tracking-wider text-[#1061D6] uppercase">
                              {schedule.category}
                            </span>
                          )}

                          {schedule.room && (
                            <span className="inline-flex items-center text-xs font-semibold text-slate-600">
                              <MapPin className="mr-1 h-3 w-3 text-slate-400" />
                              {schedule.room}
                            </span>
                          )}
                        </div>
                      </div>

                      {/* Content details */}
                      <div className="space-y-1.5">
                        <h4 className="text-lg leading-snug font-bold text-slate-800">
                          {schedule.title}
                        </h4>
                        {schedule.description && (
                          <p className="text-sm leading-relaxed font-medium text-slate-500">
                            {schedule.description}
                          </p>
                        )}
                      </div>

                      {/* Action buttons footer */}
                      <div className="flex items-center gap-3 border-t border-slate-50 pt-3">
                        {/* Attendance State (Hanya jika absensi diaktifkan) */}
                        {pelatihan.attendanceRequired ? (
                          isCheckedIn ? (
                            attendanceType === "present" ? (
                              <div className="inline-flex items-center gap-2 rounded-xl border border-[#1F6A3B]/10 bg-[#B8F4CF] px-4 py-2 text-sm font-semibold text-[#1F6A3B]">
                                <Check className="h-4 w-4" />
                                Hadir
                              </div>
                            ) : (
                              <div className="inline-flex items-center gap-2 rounded-xl border border-[#D79200]/10 bg-[#FFECC3] px-4 py-2 text-sm font-semibold text-[#D79200]">
                                <Check className="h-4 w-4" />
                                Izin
                              </div>
                            )
                          ) : (
                            <Button
                              type="button"
                              onClick={() => openPresensiModal(schedule)}
                              className="rounded-xl bg-[#1061D6] px-5 text-sm font-semibold text-white transition-all duration-300 hover:scale-[1.01] hover:bg-[#0e54b8] active:scale-[0.98]"
                            >
                              Presensi
                            </Button>
                          )
                        ) : (
                          <div className="inline-flex items-center gap-1.5 rounded-xl border border-slate-200 bg-slate-50 px-3.5 py-1.5 text-xs font-semibold text-slate-500">
                            Kehadiran Opsional
                          </div>
                        )}

                        {/* Material download */}
                        {schedule.materialUrl ? (
                          <Button
                            variant="outline"
                            asChild
                            className="flex items-center gap-2 rounded-xl border-slate-200 px-4 text-sm font-semibold text-[#1061D6] transition-all duration-300 hover:scale-[1.01] hover:bg-blue-50/50 hover:text-[#1061D6] active:scale-[0.98]"
                          >
                            <a
                              href={schedule.materialUrl}
                              target="_blank"
                              rel="noreferrer"
                            >
                              <Download className="h-4 w-4" />
                              Download Materi
                            </a>
                          </Button>
                        ) : (
                          <Button
                            variant="outline"
                            disabled
                            className="flex items-center gap-2 rounded-xl border-slate-200 px-4 text-sm font-semibold text-slate-400"
                          >
                            <Download className="h-4 w-4" />
                            Materi Belum Tersedia
                          </Button>
                        )}

                        {/* Meeting link */}
                        {schedule.meetUrl && (
                          <Button
                            variant="outline"
                            asChild
                            className="flex items-center gap-2 rounded-xl border-slate-200 px-4 text-sm font-semibold text-[#1061D6] transition-all duration-300 hover:scale-[1.01] hover:bg-blue-50/50 hover:text-[#1061D6] active:scale-[0.98]"
                          >
                            <a
                              href={schedule.meetUrl}
                              target="_blank"
                              rel="noreferrer"
                            >
                              <Video className="h-4 w-4" />
                              Join Meeting
                            </a>
                          </Button>
                        )}
                      </div>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>
      </div>

      {/* Tambah Laporan Harian Modal Dialog (Checklist Absen) */}
      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="rounded-3xl p-6 sm:max-w-[440px]">
          <DialogHeader className="space-y-2">
            <DialogTitle className="text-center text-xl font-bold text-[#1061D6]">
              Tambah Laporan Harian
            </DialogTitle>
          </DialogHeader>

          {/* Form details / selection */}
          <div className="space-y-4 py-4">
            {/* Hadir option button card */}
            <button
              type="button"
              onClick={() => setAttendanceStatus("present")}
              className={cn(
                "flex w-full items-center justify-between rounded-2xl border p-4 transition-all outline-none",
                attendanceStatus === "present"
                  ? "border-[#1F6A3B] bg-[#B8F4CF] text-[#1F6A3B]"
                  : "border-slate-200 bg-white text-slate-700 hover:bg-slate-50",
              )}
            >
              <span className="text-base font-bold">Hadir</span>
              <div
                className={cn(
                  "flex h-6 w-6 items-center justify-center rounded-full border-2 transition-all",
                  attendanceStatus === "present"
                    ? "border-[#1F6A3B] bg-[#1F6A3B] text-white"
                    : "border-slate-300 bg-transparent",
                )}
              >
                {attendanceStatus === "present" && (
                  <Check className="h-3.5 w-3.5 stroke-[3]" />
                )}
              </div>
            </button>

            {/* Izin option button card */}
            <button
              type="button"
              onClick={() => setAttendanceStatus("excused")}
              className={cn(
                "flex w-full items-center justify-between rounded-2xl border p-4 transition-all outline-none",
                attendanceStatus === "excused"
                  ? "border-[#D79200] bg-[#FFECC3] text-[#D79200]"
                  : "border-slate-200 bg-white text-slate-700 hover:bg-slate-50",
              )}
            >
              <span className="text-base font-bold">Izin</span>
              <div
                className={cn(
                  "flex h-6 w-6 items-center justify-center rounded-full border-2 transition-all",
                  attendanceStatus === "excused"
                    ? "border-[#D79200] bg-[#D79200] text-white"
                    : "border-slate-300 bg-transparent",
                )}
              >
                {attendanceStatus === "excused" && (
                  <Check className="h-3.5 w-3.5 stroke-[3]" />
                )}
              </div>
            </button>
          </div>

          {/* Submit action */}
          <div className="mt-2 flex justify-end gap-3">
            <Button
              type="button"
              disabled={isSubmitting}
              onClick={handleCheckIn}
              className="h-11 w-full rounded-2xl bg-[#1061D6] text-sm font-bold text-white transition-all hover:bg-[#0e54b8]"
            >
              {isSubmitting ? "Mengirim Presensi..." : "kirim presensi"}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  );
}
